class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        reachable = 1  # bit s is set when some subset sums to s; bit 0 = empty subset
        for x in nums:
            reachable |= reachable << x
        return (reachable >> target) & 1 == 1

